/// Counts how many entries in `condition` are `true`.
pub fn count_true(condition: &[bool]) -> usize {
    condition.iter().filter(|&&b| b).count()
}

/// Returns a new vector containing `arr[i]` for each index `i` where `condition[i]` is `true`,
/// preserving the relative order of selected elements.
///
/// Precondition (assumed by the problem): `condition.len() == arr.len()`.
/// Postcondition: `result.len() == count_true(&condition)`.
pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    assert_eq!(
        condition.len(),
        arr.len(),
        "condition and arr must have equal lengths"
    );

    let k = count_true(&condition);
    let mut result = Vec::with_capacity(k);

    for i in 0..condition.len() {
        if condition[i] {
            result.push(arr[i]);
        }
    }

    // Verification of required property.
    debug_assert_eq!(result.len(), k);

    result
}

